//! Decides, for each object on the source cluster, whether it migrates.
//!
//! Rules are ordered and the first match wins. Provenance comes from the API
//! itself: k3s records every distro-installed object under a `k3s.cattle.io`
//! Addon through wrangler `objectset.rio.cattle.io/owner-*` annotations.
//! Helm labels are not a distro signal (user charts carry them identically).
//!
//! - R0 non-stored or mid-deletion: skip
//! - R1 apiserver-reconciled builtin: skip
//! - R2 distro-installed (shipped Addon, its HelmChart chain, k3s bootstrap): skip
//! - R3 generated by servicelb from a user Service: skip
//! - R4 child of a controller that regenerates it on u7s: skip
//! - R5 Addon-owned by a file k3s does not ship: migrate, warn
//! - R6 Helm: user HelmChart objects skip with a warning, other Helm objects migrate
//! - R7 everything else: migrate

use std::collections::{BTreeSet, HashMap, HashSet};

use serde::{Deserialize, Serialize};
use serde_json::Value;
use u7s_apiserver::migrate_tables::FINALIZER_ALLOWLIST;

const OWNER_GVK: &str = "objectset.rio.cattle.io/owner-gvk";
const OWNER_NAME: &str = "objectset.rio.cattle.io/owner-name";
const OWNER_NS: &str = "objectset.rio.cattle.io/owner-namespace";
const ADDON_GVK: &str = "k3s.cattle.io/v1, Kind=Addon";
const HELM_RELEASE_NAME: &str = "meta.helm.sh/release-name";
const HELM_RELEASE_NS: &str = "meta.helm.sh/release-namespace";

const SYSTEM_NAMESPACES: &[&str] = &["default", "kube-system", "kube-public", "kube-node-lease"];

/// Upstream finalizers whose controllers are part of u7s's own control plane.
const UPSTREAM_FINALIZERS: &[&str] = &[
    "kubernetes.io/pvc-protection",
    "kubernetes.io/pv-protection",
    "foregroundDeletion",
    "orphan",
    "networking.k8s.io/service-cidr-finalizer",
];

/// (owner group, owner kind, child kinds): owners whose controller runs on u7s
/// and recreates the children. Any other ownerReference (user CR to CR, a
/// StatefulSet to its PVCs) must migrate or the ownership is lost.
const REGENERATING_OWNERS: &[(&str, &str, &[&str])] = &[
    ("apps", "Deployment", &["ReplicaSet"]),
    ("apps", "ReplicaSet", &["Pod"]),
    ("apps", "StatefulSet", &["Pod", "ControllerRevision"]),
    ("apps", "DaemonSet", &["Pod", "ControllerRevision"]),
    ("batch", "Job", &["Pod"]),
    ("batch", "CronJob", &["Job"]),
    ("", "Service", &["Endpoints", "EndpointSlice"]),
];

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum Action {
    Include,
    Exclude,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Decision {
    pub rule: &'static str,
    pub class: &'static str,
    pub action: Action,
    pub reason: String,
    /// The user must look at this object even though the default is set.
    pub warn: bool,
    /// Distro component (Addon name) this object belongs to, if any.
    pub component: Option<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum FinalizerAction {
    Keep,
    Strip,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct FinalizerDecision {
    pub name: String,
    pub action: FinalizerAction,
    pub reason: String,
    pub warn: bool,
}

#[derive(Default)]
pub struct Context {
    shipped: HashSet<String>,
    /// (HelmChart name, namespace) -> owning shipped Addon.
    distro_charts: HashMap<(String, String), String>,
    /// (Helm release name, release namespace) -> owning shipped Addon.
    distro_releases: HashMap<(String, String), String>,
    selector_services: HashSet<(String, String)>,
    crd_groups: BTreeSet<String>,
    strippable: Vec<&'static str>,
}

impl Context {
    /// `shipped` is the Addon-name list for the source's k3s version and
    /// `strippable` the finalizer allowlist for that version.
    pub fn build(objs: &[Value], shipped: &[String], strippable: Vec<&'static str>) -> Self {
        let mut c = Context {
            shipped: shipped.iter().cloned().collect(),
            strippable,
            ..Default::default()
        };
        for o in objs {
            let (group, kind) = (group_of(o), kind(o));
            if group == "helm.cattle.io" && kind == "HelmChart" {
                if let Some(addon) = owner_addon(o).filter(|a| c.shipped.contains(*a)) {
                    let ns = namespace(o).unwrap_or_default().to_string();
                    let target = o["spec"]["targetNamespace"].as_str().unwrap_or(&ns);
                    c.distro_releases
                        .insert((name(o).to_string(), target.to_string()), addon.to_string());
                    c.distro_charts
                        .insert((name(o).to_string(), ns), addon.to_string());
                }
            }
            if group.is_empty() && kind == "Service" {
                let has_selector = o["spec"]["selector"]
                    .as_object()
                    .is_some_and(|s| !s.is_empty());
                if has_selector {
                    c.selector_services.insert((
                        namespace(o).unwrap_or_default().to_string(),
                        name(o).to_string(),
                    ));
                }
            }
            if kind == "CustomResourceDefinition" {
                if let Some(g) = o["spec"]["group"].as_str() {
                    c.crd_groups.insert(g.to_string());
                }
            }
        }
        c
    }

    /// Shipped Addons that no object in `objs` references. A mismatch means the
    /// wrangler annotation format changed and distro objects would be migrated
    /// as user data.
    pub fn unreferenced_addons(&self, objs: &[Value]) -> Vec<String> {
        let referenced: HashSet<&str> = objs.iter().filter_map(owner_addon).collect();
        let mut v: Vec<String> = objs
            .iter()
            .filter(|o| group_of(o) == "k3s.cattle.io" && kind(o) == "Addon")
            .map(|o| name(o).to_string())
            .filter(|n| self.shipped.contains(n) && !referenced.contains(n.as_str()))
            .collect();
        v.sort();
        v
    }
}

pub fn api_version(o: &Value) -> &str {
    o["apiVersion"].as_str().unwrap_or_default()
}

pub fn kind(o: &Value) -> &str {
    o["kind"].as_str().unwrap_or_default()
}

pub fn name(o: &Value) -> &str {
    o["metadata"]["name"].as_str().unwrap_or_default()
}

pub fn namespace(o: &Value) -> Option<&str> {
    o["metadata"]["namespace"].as_str()
}

fn group_of(o: &Value) -> &str {
    api_version(o).split_once('/').map_or("", |(g, _)| g)
}

fn annotation<'a>(o: &'a Value, key: &str) -> Option<&'a str> {
    o["metadata"]["annotations"][key].as_str()
}

fn label<'a>(o: &'a Value, key: &str) -> Option<&'a str> {
    o["metadata"]["labels"][key].as_str()
}

fn owner_addon(o: &Value) -> Option<&str> {
    (annotation(o, OWNER_GVK)? == ADDON_GVK)
        .then(|| annotation(o, OWNER_NAME))
        .flatten()
}

fn has_manager_prefix(o: &Value, prefix: &str) -> bool {
    o["metadata"]["managedFields"].as_array().is_some_and(|m| {
        m.iter()
            .any(|f| f["manager"].as_str().is_some_and(|m| m.starts_with(prefix)))
    })
}

/// (release name, release namespace) of a Helm-installed object.
fn helm_release(o: &Value) -> Option<(String, String)> {
    if let (Some(n), Some(ns)) = (
        annotation(o, HELM_RELEASE_NAME),
        annotation(o, HELM_RELEASE_NS),
    ) {
        return Some((n.to_string(), ns.to_string()));
    }
    if kind(o) == "Secret" && o["type"].as_str() == Some("helm.sh/release.v1") {
        return Some((label(o, "name")?.to_string(), namespace(o)?.to_string()));
    }
    None
}

/// HelmChart that helm-controller built this scaffolding object for.
fn scaffold_owner(o: &Value) -> Option<(String, String)> {
    annotation(o, OWNER_GVK)?
        .ends_with("Kind=HelmChart")
        .then(|| {
            Some((
                annotation(o, OWNER_NAME)?.to_string(),
                annotation(o, OWNER_NS)?.to_string(),
            ))
        })
        .flatten()
}

fn decision(
    rule: &'static str,
    class: &'static str,
    action: Action,
    reason: impl Into<String>,
) -> Decision {
    Decision {
        rule,
        class,
        action,
        reason: reason.into(),
        warn: false,
        component: None,
    }
}

fn skip(rule: &'static str, class: &'static str, reason: impl Into<String>) -> Decision {
    decision(rule, class, Action::Exclude, reason)
}

fn migrate(rule: &'static str, class: &'static str, reason: impl Into<String>) -> Decision {
    decision(rule, class, Action::Include, reason)
}

fn warned(mut d: Decision) -> Decision {
    d.warn = true;
    d
}

pub fn classify(o: &Value, c: &Context) -> Decision {
    if let Some(d) = non_stored(o) {
        return d;
    }
    if let Some(why) = builtin(o, c) {
        return skip("R1", "apiserver-builtin", why);
    }
    if let Some((component, why)) = distro(o, c) {
        let mut d = skip("R2", "distro", why);
        d.component = Some(component);
        return d;
    }
    let svc = label(o, "svccontroller.k3s.cattle.io/svcname").or_else(|| {
        annotation(o, OWNER_GVK)
            .is_some_and(|g| g.ends_with("Kind=Service"))
            .then(|| annotation(o, OWNER_NAME))
            .flatten()
    });
    if let Some(svc) = svc {
        let ns = label(o, "svccontroller.k3s.cattle.io/svcnamespace")
            .or_else(|| annotation(o, OWNER_NS))
            .unwrap_or_default();
        return skip(
            "R3",
            "servicelb-child",
            format!("generated by servicelb for Service {ns}/{svc}; no LoadBalancer implementation on u7s"),
        );
    }
    if let Some(owner) = regenerating_owner(o) {
        return skip(
            "R4",
            "controller-child",
            format!("{owner} is recreated by its controller on u7s"),
        );
    }
    if let Some(addon) = owner_addon(o) {
        return warned(migrate(
            "R5",
            "user-manifest-file",
            format!(
                "Addon {addon} is not a manifest this k3s version ships: a file the user placed in the auto-deploy folder; u7s does not honour that folder, apply the file yourself in future"
            ),
        ));
    }
    if let Some(d) = helm(o) {
        return d;
    }
    refine_user(o)
}

fn non_stored(o: &Value) -> Option<Decision> {
    let (group, kind) = (group_of(o), kind(o));
    let why = match (group, kind) {
        ("metrics.k8s.io", _) => "aggregated API, not stored",
        ("" | "events.k8s.io", "Event") => "events are not migrated",
        ("", "ComponentStatus") => "computed, not stored",
        ("", "Node") => "the u7s kubelet registers its own Node",
        ("storage.k8s.io", "CSINode") => "created by the u7s kubelet when its CSI drivers register",
        ("storage.k8s.io", "VolumeAttachment") => {
            "recreated by the attach/detach controller when the volume attaches on u7s"
        }
        _ => {
            return o["metadata"]["deletionTimestamp"].as_str().map(|ts| {
                let fins = finalizers(o);
                skip(
                    "R0",
                    "mid-deletion",
                    format!(
                        "being deleted since {ts}; finalizers still held: [{}]",
                        fins.join(", ")
                    ),
                )
            })
        }
    };
    Some(skip("R0", "non-stored", why))
}

fn builtin(o: &Value, c: &Context) -> Option<String> {
    let (group, kind) = (group_of(o), kind(o));
    let name = name(o);
    let ns = namespace(o).unwrap_or_default();
    if label(o, "kubernetes.io/bootstrapping").is_some()
        || annotation(o, "rbac.authorization.kubernetes.io/autoupdate").is_some()
    {
        return Some("bootstrap RBAC object reconciled by the u7s apiserver".into());
    }
    let why = match (group, kind) {
        ("", "Namespace") if SYSTEM_NAMESPACES.contains(&name) => {
            "system namespace, created by u7s"
        }
        ("", "ServiceAccount") if name == "default" => {
            "default ServiceAccount, created per namespace by u7s"
        }
        ("", "ServiceAccount")
            if ns == "kube-system" && o["metadata"]["managedFields"].is_null() =>
        {
            "control-plane controller ServiceAccount created in-process"
        }
        ("", "ConfigMap") if name == "kube-root-ca.crt" => {
            "CA bundle ConfigMap, created per namespace by u7s"
        }
        ("", "ConfigMap")
            if ns == "kube-system" && name == "extension-apiserver-authentication" =>
        {
            "generated by the u7s apiserver"
        }
        ("", "ConfigMap")
            if ns == "kube-system"
                && name == "kube-apiserver-legacy-service-account-token-tracking" =>
        {
            "kube-apiserver token-tracking bookkeeping, not user data"
        }
        ("", "Service" | "Endpoints") | ("discovery.k8s.io", "EndpointSlice")
            if ns == "default" && name == "kubernetes" =>
        {
            "apiserver Service and its endpoints, created by u7s"
        }
        ("scheduling.k8s.io", "PriorityClass")
            if matches!(name, "system-cluster-critical" | "system-node-critical") =>
        {
            "built-in PriorityClass; u7s resolves it by name with its fixed value"
        }
        ("flowcontrol.apiserver.k8s.io", _)
            if annotation(o, "apf.kubernetes.io/autoupdate-spec").is_some() =>
        {
            "suggested API priority/fairness object reconciled by the u7s apiserver"
        }
        ("apiregistration.k8s.io", "APIService")
            if label(o, "kube-aggregator.kubernetes.io/automanaged").is_some() =>
        {
            "automanaged APIService reconciled by the u7s apiserver"
        }
        ("networking.k8s.io", "ServiceCIDR" | "IPAddress") => "allocator state rebuilt by u7s",
        ("coordination.k8s.io", "Lease") => "leader-election and node-heartbeat state",
        ("", "Endpoints")
            if c.selector_services
                .contains(&(ns.to_string(), name.to_string())) =>
        {
            "maintained by the endpoints controller for a selector Service"
        }
        ("discovery.k8s.io", "EndpointSlice")
            if label(o, "endpointslice.kubernetes.io/managed-by").is_some_and(|m| {
                m == "endpointslice-controller.k8s.io"
                    || m == "endpointslicemirroring-controller.k8s.io"
            }) =>
        {
            "maintained by the endpointslice controller"
        }
        _ => return None,
    };
    Some(why.to_string())
}

fn distro(o: &Value, c: &Context) -> Option<(String, String)> {
    if let Some(addon) = owner_addon(o).filter(|a| c.shipped.contains(*a)) {
        return Some((addon.to_string(), format!("installed by k3s Addon {addon}")));
    }
    if let Some(rel) = helm_release(o) {
        if let Some(addon) = c.distro_releases.get(&rel) {
            return Some((
                addon.clone(),
                format!(
                    "Helm release {}/{} of the HelmChart owned by k3s Addon {addon}",
                    rel.1, rel.0
                ),
            ));
        }
    }
    if let Some(chart) = scaffold_owner(o) {
        if let Some(addon) = c.distro_charts.get(&chart) {
            return Some((
                addon.clone(),
                format!(
                    "helm-controller scaffolding for HelmChart {}/{} (k3s Addon {addon})",
                    chart.1, chart.0
                ),
            ));
        }
    }
    let k3s = |why: &str| Some(("k3s".to_string(), why.to_string()));
    let (group, kind) = (group_of(o), kind(o));
    if group == "k3s.cattle.io" {
        return k3s("k3s Addon bookkeeping");
    }
    if kind == "CustomResourceDefinition"
        && matches!(
            o["spec"]["group"].as_str(),
            Some("k3s.cattle.io" | "helm.cattle.io")
        )
    {
        return k3s("CRD of the k3s-embedded Addon/helm controllers");
    }
    if has_manager_prefix(o, "k3s-supervisor@") {
        return k3s("k3s bootstrap state written by the k3s supervisor");
    }
    None
}

fn regenerating_owner(o: &Value) -> Option<String> {
    let kind = kind(o);
    o["metadata"]["ownerReferences"]
        .as_array()?
        .iter()
        .find_map(|r| {
            let (g, k) = (
                r["apiVersion"]
                    .as_str()?
                    .split_once('/')
                    .map_or("", |(g, _)| g),
                r["kind"].as_str()?,
            );
            REGENERATING_OWNERS
                .iter()
                .any(|(og, ok, kids)| *og == g && *ok == k && kids.contains(&kind))
                .then(|| format!("{k} {}", r["name"].as_str().unwrap_or_default()))
        })
}

fn helm(o: &Value) -> Option<Decision> {
    let (group, kind) = (group_of(o), kind(o));
    if group == "helm.cattle.io" {
        return Some(warned(skip(
            "R6",
            "user-helmchart",
            format!(
                "{kind} for k3s's embedded helm-controller; u7s has none and the {group} CRDs are not migrated"
            ),
        )));
    }
    if let Some((n, ns)) = scaffold_owner(o) {
        return Some(warned(skip(
            "R6",
            "user-helmchart",
            format!(
                "helm-controller scaffolding for HelmChart {ns}/{n}; u7s has no helm-controller"
            ),
        )));
    }
    let rel = helm_release(o).or_else(|| {
        (label(o, "app.kubernetes.io/managed-by") == Some("Helm")).then(|| {
            (
                label(o, "app.kubernetes.io/instance")
                    .unwrap_or("?")
                    .to_string(),
                namespace(o).unwrap_or_default().to_string(),
            )
        })
    })?;
    Some(migrate(
        "R6",
        "user-helm",
        format!(
            "Helm release {}/{}; release state moves as a Secret but charts are not re-rendered",
            rel.1, rel.0
        ),
    ))
}

fn refine_user(o: &Value) -> Decision {
    let (group, kind) = (group_of(o), kind(o));
    if group.is_empty() && kind == "Service" && o["spec"]["type"].as_str() == Some("LoadBalancer") {
        return warned(migrate(
            "R7",
            "user",
            "LoadBalancer Service: status.loadBalancer is dropped and u7s has no servicelb",
        ));
    }
    if group.is_empty()
        && kind == "PersistentVolume"
        && o["spec"]["persistentVolumeReclaimPolicy"].as_str() == Some("Delete")
    {
        return warned(migrate(
            "R7",
            "user",
            "reclaimPolicy Delete: the source copy is switched to Retain at cutover, the imported PV keeps Delete",
        ));
    }
    migrate("R7", "user", "user or third-party object")
}

pub fn finalizers(o: &Value) -> Vec<&str> {
    o["metadata"]["finalizers"]
        .as_array()
        .map(|a| a.iter().filter_map(Value::as_str).collect())
        .unwrap_or_default()
}

/// One decision per finalizer on an object that will migrate. Only exact
/// allowlisted names are ever stripped; everything else is kept.
pub fn finalizer_decisions(o: &Value, c: &Context) -> Vec<FinalizerDecision> {
    finalizers(o)
        .into_iter()
        .map(|f| {
            let fd = |action, reason: String, warn| FinalizerDecision {
                name: f.to_string(),
                action,
                reason,
                warn,
            };
            if c.strippable.contains(&f) {
                let why = FINALIZER_ALLOWLIST
                    .iter()
                    .find(|e| e.name == f)
                    .map_or("", |e| e.justification);
                return fd(FinalizerAction::Strip, why.to_string(), false);
            }
            if UPSTREAM_FINALIZERS.contains(&f) {
                return fd(
                    FinalizerAction::Keep,
                    "upstream finalizer, u7s runs its controller".into(),
                    false,
                );
            }
            let domain = f.split('/').next().unwrap_or(f);
            if let Some(g) = c
                .crd_groups
                .iter()
                .find(|g| domain == g.as_str() || domain.ends_with(&format!(".{g}")))
            {
                return fd(
                    FinalizerAction::Keep,
                    format!("controller likely migrated with CRD group {g}"),
                    false,
                );
            }
            fd(
                FinalizerAction::Keep,
                format!(
                    "no migrated CRD matches the domain of {f}; if its controller is not migrated this object will not finish deleting; to remove only this entry later: kubectl patch with a JSON-patch remove of this one finalizer (never finalizers: null)"
                ),
                true,
            )
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn ctx(objs: &[Value]) -> Context {
        let shipped: Vec<String> = ["coredns", "traefik", "local-storage"]
            .iter()
            .map(|s| s.to_string())
            .collect();
        Context::build(
            objs,
            &shipped,
            vec!["wrangler.cattle.io/on-helm-chart-remove"],
        )
    }

    fn pod_owned_by(api: &str, kind: &str, child: &str) -> Value {
        json!({"apiVersion": "v1", "kind": child,
            "metadata": {"name": "c", "namespace": "n",
                "ownerReferences": [{"apiVersion": api, "kind": kind, "name": "o"}]}})
    }

    #[test]
    fn owner_ref_skip_is_limited_to_kinds_u7s_regenerates() {
        let c = ctx(&[]);
        assert_eq!(
            classify(&pod_owned_by("apps/v1", "ReplicaSet", "Pod"), &c).action,
            Action::Exclude,
            "pods of a ReplicaSet are recreated by the ReplicaSet controller"
        );
        for (api, kind, child) in [
            ("apps/v1", "StatefulSet", "PersistentVolumeClaim"),
            ("example.com/v1", "Widget", "Gadget"),
        ] {
            assert_eq!(
                classify(&pod_owned_by(api, kind, child), &c).action,
                Action::Include,
                "{kind} owning {child}: no u7s controller regenerates it, skipping would drop user data or ownership"
            );
        }
    }

    #[test]
    fn helm_release_match_includes_namespace() {
        let chart = json!({"apiVersion": "helm.cattle.io/v1", "kind": "HelmChart",
            "metadata": {"name": "traefik", "namespace": "kube-system", "annotations": {
                OWNER_GVK: ADDON_GVK, OWNER_NAME: "traefik"}}});
        let release_obj = |ns: &str| {
            json!({"apiVersion": "v1", "kind": "ConfigMap",
            "metadata": {"name": "x", "namespace": ns, "annotations": {
                HELM_RELEASE_NAME: "traefik", HELM_RELEASE_NS: ns}}})
        };
        let c = ctx(&[chart]);
        assert_eq!(classify(&release_obj("kube-system"), &c).rule, "R2");
        assert_eq!(
            classify(&release_obj("userapp"), &c).rule,
            "R6",
            "a user release that reuses the name 'traefik' in another namespace is user data"
        );
    }

    #[test]
    fn addon_from_unshipped_file_migrates_rather_than_looping_into_distro() {
        let cm = json!({"apiVersion": "v1", "kind": "ConfigMap",
            "metadata": {"name": "dropped-in", "namespace": "default", "annotations": {
                OWNER_GVK: ADDON_GVK, OWNER_NAME: "my-app"}}});
        let d = classify(&cm, &ctx(&[]));
        assert_eq!((d.rule, d.action, d.warn), ("R5", Action::Include, true));
    }

    #[test]
    fn selectorless_endpoints_are_user_data() {
        let svc = |sel: Value| {
            json!({"apiVersion": "v1", "kind": "Service",
            "metadata": {"name": "ext", "namespace": "n"}, "spec": {"selector": sel}})
        };
        let ep = json!({"apiVersion": "v1", "kind": "Endpoints",
            "metadata": {"name": "ext", "namespace": "n"}});
        assert_eq!(
            classify(&ep, &ctx(&[svc(json!({"a": "b"}))])).action,
            Action::Exclude
        );
        assert_eq!(
            classify(&ep, &ctx(&[svc(json!(null))])).action,
            Action::Include,
            "hand-written Endpoints for an external service are not regenerated by any controller"
        );
    }

    #[test]
    fn only_allowlisted_finalizers_are_stripped() {
        let o = json!({"apiVersion": "v1", "kind": "Service",
            "metadata": {"name": "s", "namespace": "n", "finalizers": [
                "wrangler.cattle.io/on-helm-chart-remove",
                "wrangler.cattle.io/node",
                "kubernetes.io/pvc-protection",
                "foo.example.com/x"]}});
        let acts: Vec<_> = finalizer_decisions(&o, &ctx(&[]))
            .into_iter()
            .map(|d| (d.name, d.action, d.warn))
            .collect();
        assert_eq!(
            acts,
            [
                ("wrangler.cattle.io/on-helm-chart-remove".into(), FinalizerAction::Strip, false),
                ("wrangler.cattle.io/node".into(), FinalizerAction::Keep, true),
                ("kubernetes.io/pvc-protection".into(), FinalizerAction::Keep, false),
                ("foo.example.com/x".into(), FinalizerAction::Keep, true),
            ],
            "a wildcard or an out-of-range allowlist entry would strip finalizers whose controller we cannot verify"
        );
    }
}
